 "content": "def transform(grid):
    """Trace the 2-colored channel through successive horizontal barriers."""
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    barriers = [r for r,row in enumerate(a) if sum(v == 8 for v in row) >= max(2, w//2)]
    if not barriers:
        return a
    ports = {r: [c for c,v in enumerate(a[r]) if v == 0] for r in barriers}
    # Mark each opening in each barrier and the corridor immediately above it.
    for i,r in enumerate(barriers):
        holes = ports[r]
        if holes:
            lo, hi = (0, w-1) if len(holes) == 1 else (min(holes), max(holes))
            if r > 0:
                for c in range(lo, hi+1):
                    if a[r-1][c] == 0: a[r-1][c] = 2
            for c in holes:
                if a[r][c] == 0: a[r][c] = 2
        # Carry the open channels down to the next barrier.
        end = barriers[i+1] if i+1 < len(barriers) else h
        for rr in range(r+1, end):
            for c in holes:
                if a[rr][c] == 0: a[rr][c] = 2
    return a
"
}

